-- C-04: subsidiaries, branches, currencies and configuration references.
set local lock_timeout='5s';set local statement_timeout='60s';
create schema company_master_private;revoke all on schema company_master_private from public,anon,authenticated,service_role;grant usage on schema company_master_private to authenticated;
do $patch$declare source text;begin source:=pg_get_functiondef('organization_master_private.meta(text)'::regprocedure);if position('))c(k,t,pk,links,fields)'in source)=0 then raise exception 'Unexpected organization metadata';end if;execute replace(source,'))c(k,t,pk,links,fields)',$meta$),('subsidiaries','subsidiaries','subsidiary_id',null,array['name','legal_name','parent_id','country_id','currency_id','fiscal_calendar_id','tax_id','is_elimination','is_active','timezone_id','logo_url','address','email','phone','administrative_approver','tax_supervisor_user_id','applies_income_autorent','autorent_active_account_id','autorent_passive_account_id','autorent_percentage','default_up_approver_id']),('branches','branches','branch_id',null,array['branch_code','name','subsidiary_id','address']))c(k,t,pk,links,fields)$meta$);end$patch$;
create function company_master_private.member(id bigint)returns boolean language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select exists(select 1 from public.users u join public.user_subsidiaries us using(user_id)where u.user_id=public.app_user_id()and u.is_active and us.subsidiary_id=id)$$;
create function company_master_private.branch_visible(sid bigint)returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin return sid=entity_master_private.identity()and company_master_private.member(sid)and organization_master_private.allowed('branches','view');exception when insufficient_privilege then return false;end$$;
create function company_master_private.up_allowed()returns boolean language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select exists(select 1 from public.role_permissions rp join public.permissions p using(permission_id)where rp.role_id=public.app_active_role_id()and p.code='ORG_UP_APPROVER_MANAGE')$$;
create function company_master_private.used(id bigint)returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare f record;b boolean;begin for f in select n.nspname,c.relname,a.attname,cardinality(co.conkey)len from pg_constraint co join pg_class c on c.oid=co.conrelid join pg_namespace n on n.oid=c.relnamespace join pg_attribute a on a.attrelid=c.oid and a.attnum=co.conkey[1]where co.contype='f'and co.confrelid='public.subsidiaries'::regclass and c.relname not in('user_subsidiaries','user_company_sessions','subsidiary_currencies','account_subsidiaries')loop if f.len<>1 then return true;end if;execute format('select exists(select 1 from %I.%I where %I=$1)',f.nspname,f.relname,f.attname)into b using id;if b then return true;end if;end loop;return false;end$$;
create function company_master_private.fingerprint(id bigint)returns text language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select md5(jsonb_build_array(to_jsonb(s),coalesce((select jsonb_agg(to_jsonb(c)order by currency_id)from public.subsidiary_currencies c where c.subsidiary_id=s.subsidiary_id),'[]'))::text)from public.subsidiaries s where s.subsidiary_id=id$$;
create function company_master_private.dto(s public.subsidiaries,detail boolean default false)returns jsonb language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select(case when detail then to_jsonb(s)else to_jsonb(s)-'logo_url'end)||jsonb_build_object('secondary_currency_ids',coalesce((select jsonb_agg(currency_id order by currency_id)from public.subsidiary_currencies where subsidiary_id=s.subsidiary_id and currency_id<>s.currency_id),'[]'),'allowed_currency_ids',(select jsonb_agg(x order by x)from(select s.currency_id x union select currency_id from public.subsidiary_currencies where subsidiary_id=s.subsidiary_id)t),'_revision',company_master_private.fingerprint(s.subsidiary_id),'_actions',jsonb_build_object('canEdit',organization_master_private.allowed('subsidiaries','edit')and company_master_private.member(s.subsidiary_id),'canDelete',false))$$;
create function company_master_private.list(k text)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=organization_master_private.access(k,'view');begin if k='subsidiaries'then return coalesce((select jsonb_agg(company_master_private.dto(s)order by s.subsidiary_id)from public.subsidiaries s where company_master_private.member(s.subsidiary_id)),'[]');end if;return coalesce((select jsonb_agg(to_jsonb(b)||jsonb_build_object('_revision',md5(to_jsonb(b)::text),'_actions',jsonb_build_object('canEdit',organization_master_private.allowed(k,'edit'),'canDelete',organization_master_private.allowed(k,'delete')and not entity_master_private.used('branches',b.branch_id)))order by b.branch_id)from public.branches b where b.subsidiary_id=sid),'[]');end$$;
create function public.organization_company_detail(p_id bigint)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare s public.subsidiaries;begin perform organization_master_private.access('subsidiaries','view');if p_id is null or not company_master_private.member(p_id)then raise exception using errcode='42501',message='Subsidiaria no autorizada.';end if;select *into s from public.subsidiaries where subsidiary_id=p_id;if not found then raise exception using errcode='42501',message='Subsidiaria no disponible.';end if;return company_master_private.dto(s,true);end$$;
create function company_master_private.options(k text)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=organization_master_private.access(k,'view');refs jsonb;begin
 refs:=jsonb_build_object('organization/subsidiaries',coalesce((select jsonb_agg(jsonb_build_object('subsidiary_id',s.subsidiary_id,'name',s.name,'country_id',s.country_id))from public.subsidiaries s where company_master_private.member(s.subsidiary_id)and(k='subsidiaries'or s.subsidiary_id=sid)),'[]'));
 if k='subsidiaries'then refs:=refs||jsonb_build_object(
 'core/countries',coalesce((select jsonb_agg(jsonb_build_object('country_id',country_id,'name',name,'country_code_iso2',country_code_iso2,'country_code_iso3',country_code_iso3))from public.countries),'[]'),
 'core/currencies',coalesce((select jsonb_agg(jsonb_build_object('currency_id',currency_id,'currency_code',currency_code,'name',name))from public.currencies),'[]'),
 'core/timezones',coalesce((select jsonb_agg(jsonb_build_object('timezone_id',timezone_id,'name',name))from public.timezones where is_active),'[]'),
 'organization/fiscal-calendars',coalesce((select jsonb_agg(jsonb_build_object('fiscal_calendar_id',fiscal_calendar_id,'calendar_name',calendar_name,'fiscal_year_id',fiscal_year_id))from public.fiscal_calendars),'[]'),
 'security/users',coalesce((select jsonb_agg(jsonb_build_object('user_id',u.user_id,'first_name',u.first_name,'last_name',u.last_name,'email',u.email,'subsidiary_ids',(select jsonb_agg(us.subsidiary_id)from public.user_subsidiaries us where us.user_id=u.user_id and company_master_private.member(us.subsidiary_id))))from public.users u where u.is_active and exists(select 1 from public.user_subsidiaries us where us.user_id=u.user_id and company_master_private.member(us.subsidiary_id))),'[]'),
 'organization/up-approver-options',coalesce((select jsonb_agg(jsonb_build_object('id',u.user_id,'name',btrim(concat_ws(' ',u.first_name,u.last_name)),'email',u.email,'subsidiary_ids',(select jsonb_agg(us.subsidiary_id)from public.user_subsidiaries us where us.user_id=u.user_id and company_master_private.member(us.subsidiary_id))))from public.users u where u.is_active and exists(select 1 from public.user_subsidiaries us where us.user_id=u.user_id and company_master_private.member(us.subsidiary_id))),'[]'),
 'organization/approver-options',coalesce((select jsonb_agg(x)from(select jsonb_build_object('approver_id','user:'||u.user_id,'name',btrim(concat_ws(' ',u.first_name,u.last_name)),'is_active',true,'subsidiary_ids',(select jsonb_agg(us.subsidiary_id)from public.user_subsidiaries us where us.user_id=u.user_id and company_master_private.member(us.subsidiary_id)))x from public.users u where u.is_active and exists(select 1 from public.user_subsidiaries us where us.user_id=u.user_id and company_master_private.member(us.subsidiary_id))union all select jsonb_build_object('approver_id','employee:'||e.employee_id,'name',btrim(concat_ws(' ',e.first_name,e.last_name)),'is_active',true,'subsidiary_ids',jsonb_build_array(e.subsidiary_id))from public.employees e where e.is_active and company_master_private.member(e.subsidiary_id)and e.user_id is not null and exists(select 1 from public.users u join public.user_subsidiaries us using(user_id)where u.user_id=e.user_id and u.is_active and us.subsidiary_id=e.subsidiary_id))t),'[]'),
 'accounting/chart-accounts',coalesce((select jsonb_agg(to_jsonb(a)||jsonb_build_object('subsidiary_ids',(select jsonb_agg(s.subsidiary_id)from public.account_subsidiaries s where s.account_id=a.account_id and s.is_active and company_master_private.member(s.subsidiary_id))))from public.chart_accounts a where not a.is_inactive and a.accepts_entries and exists(select 1 from public.account_subsidiaries s where s.account_id=a.account_id and s.is_active and company_master_private.member(s.subsidiary_id))),'[]'));end if;
 return jsonb_build_object('canView',true,'canCreate',organization_master_private.allowed(k,'create'),'canEdit',organization_master_private.allowed(k,'edit'),'canDelete',k='branches'and organization_master_private.allowed(k,'delete'),'references',refs);end$$;
create function company_master_private.optional_ids(p jsonb)returns bigint[]language plpgsql immutable set search_path=pg_catalog,public,pg_temp as $$begin if jsonb_typeof(p)is distinct from'array'then raise exception using errcode='22023',message='Seleccione monedas válidas.';end if;if jsonb_array_length(p)=0 then return'{}';end if;return entity_master_private.ids(p);end$$;
create function company_master_private.save(k text,p jsonb,id bigint)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=organization_master_private.access(k,case when id is null then'create'else'edit'end);c record;oldrow jsonb;data jsonb;r jsonb;field text;cols text;vals text;sets text;oldcurr bigint[];secondary bigint[];curr bigint[];parent bigint;target_id bigint:=id;cycle boolean;used boolean;chosen bigint;kind text;percentage numeric;begin
 select *into c from organization_master_private.meta(k);if id<=0 or id>9007199254740991 or jsonb_typeof(p)is distinct from'object'or pg_column_size(p)>2000000 or exists(select 1 from jsonb_object_keys(p)x where not x=any(c.fields||array['_revision','secondary_currency_ids']))or(k='branches'and p?'secondary_currency_ids')then raise exception using errcode='22023',message='Campos de empresa inválidos.';end if;perform pg_advisory_xact_lock(793151,1);
 if id is not null then execute format('select to_jsonb(x)from public.%I x where %I=$1 for update',c.t,c.pk)into oldrow using id;if oldrow is null or(k='subsidiaries'and not company_master_private.member(id))or(k='branches'and(oldrow->>'subsidiary_id')::bigint<>sid)then raise exception using errcode='42501',message='Empresa o sucursal no autorizada.';end if;
 if p->>'_revision'is distinct from(case k when'subsidiaries'then company_master_private.fingerprint(id)else md5(oldrow::text)end)then raise exception using errcode='55000',message='El registro cambió. Consúltelo nuevamente.';end if;end if;
 data:=coalesce(oldrow,jsonb_build_object('is_active',true,'is_elimination',false,'applies_income_autorent',false,'subsidiary_id',sid))||(p-'_revision'-'secondary_currency_ids');
 foreach field in array c.fields loop
 if field in('is_active','is_elimination','applies_income_autorent')then if jsonb_typeof(data->field)is distinct from'boolean'then raise exception using errcode='22023',message='Las opciones de empresa deben ser booleanas.';end if;
 elsif field like'%_id'and field<>'tax_id'then if data->>field=''then data:=jsonb_set(data,array[field],'null');end if;if data->>field is not null and(data->>field!~'^[1-9][0-9]{0,15}$'or(data->>field)::numeric>9007199254740991)then raise exception using errcode='22023',message='Referencia inválida.';end if;
 elsif field<>'autorent_percentage'and data->>field is not null then if jsonb_typeof(data->field)is distinct from'string'then raise exception using errcode='22023',message='Texto de empresa inválido.';end if;data:=jsonb_set(data,array[field],coalesce(to_jsonb(nullif(btrim(data->>field),'')),'null'));end if;end loop;
 if nullif(data->>'name','')is null or length(data->>'name')>250 or length(coalesce(data->>'address',''))>4000 then raise exception using errcode='22023',message='Nombre o dirección inválidos.';end if;
 if k='branches'then
 if(data->>'subsidiary_id')::bigint is distinct from sid then raise exception using errcode='42501',message='Mantenga la sucursal en la filial activa.';end if;if nullif(data->>'branch_code','')is null or length(data->>'branch_code')>80 then raise exception using errcode='22023',message='Código de sucursal inválido.';end if;
 if id is not null and entity_master_private.used('branches',id)and data->>'branch_code'is distinct from oldrow->>'branch_code'then raise exception using errcode='55000',message='La sucursal utilizada conserva su código.';end if;
 else
 if nullif(data->>'legal_name','')is null or length(data->>'legal_name')>250 or nullif(data->>'tax_id','')is null or length(data->>'tax_id')>100 or length(coalesce(data->>'phone',''))>80 or(data->>'email'is not null and(length(data->>'email')>254 or data->>'email'!~'^[^[:space:]@,;<>]+@[^[:space:]@,;<>]+\.[^[:space:]@,;<>]+$'))then raise exception using errcode='22023',message='Datos legales o de contacto inválidos.';end if;
 if not exists(select 1 from public.countries where country_id=(data->>'country_id')::bigint)or not exists(select 1 from public.currencies where currency_id=(data->>'currency_id')::bigint)or not exists(select 1 from public.timezones where timezone_id=(data->>'timezone_id')::bigint and is_active)or not exists(select 1 from public.fiscal_calendars where fiscal_calendar_id=(data->>'fiscal_calendar_id')::bigint)then raise exception using errcode='42501',message='País, moneda, calendario o zona horaria no disponibles.';end if;
 if data->>'logo_url'is distinct from oldrow->>'logo_url'and data->>'logo_url'is not null and(length(data->>'logo_url')>1500000 or data->>'logo_url'!~'^(https://[^[:space:]]+|data:image/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+)$')then raise exception using errcode='22023',message='Logo inválido. Use PNG, JPG, WebP o una URL HTTPS.';end if;
 if p?'autorent_percentage'and data->>'autorent_percentage'is not null then percentage:=(data->>'autorent_percentage')::numeric;if not asset_posting_private.finite(percentage)or percentage<0 or percentage>1 then raise exception using errcode='22023',message='Porcentaje inválido.';end if;end if;
 execute format('select to_jsonb(jsonb_populate_record(null::public.%I,$1))',c.t)into data using data;
 select coalesce(array_agg(currency_id),'{}')into oldcurr from public.subsidiary_currencies where subsidiary_id=id;
 secondary:=case when p?'secondary_currency_ids'then company_master_private.optional_ids(p->'secondary_currency_ids')else array(select x from unnest(oldcurr)x where x<>(data->>'currency_id')::bigint)end;
 if(data->>'currency_id')::bigint=any(secondary)or exists(select 1 from unnest(secondary)x where not exists(select 1 from public.currencies where currency_id=x))then raise exception using errcode='22023',message='Monedas secundarias inválidas o repetidas con la principal.';end if;curr:=array[(data->>'currency_id')::bigint]||secondary;
 parent:=(data->>'parent_id')::bigint;if parent is not null then if not company_master_private.member(parent)or not exists(select 1 from public.subsidiaries where subsidiary_id=parent and is_active)then raise exception using errcode='42501',message='Subsidiaria padre no autorizada.';end if;
 with recursive chain(id,parent,path)as(select subsidiary_id,parent_id,array[subsidiary_id]from public.subsidiaries where subsidiary_id=parent union all select s.subsidiary_id,s.parent_id,ancestor.path||s.subsidiary_id from public.subsidiaries s join chain ancestor on s.subsidiary_id=ancestor.parent where not s.subsidiary_id=any(ancestor.path))select exists(select 1 from chain where chain.id=target_id)or exists(select 1 from chain where chain.parent=any(path))into cycle;
 if cycle then raise exception using errcode='22023',message='La jerarquía de subsidiarias no puede tener ciclos.';end if;end if;
 if id is null and((data->>'applies_income_autorent')::boolean or data->>'default_up_approver_id'is not null or data->>'administrative_approver'is not null or data->>'tax_supervisor_user_id'is not null)then raise exception using errcode='22023',message='Configure autorretención y aprobadores después de crear la filial y asignar acceso.';end if;
 if id is not null then used:=company_master_private.used(id);
 if used and(data->>'country_id'is distinct from oldrow->>'country_id'or data->>'currency_id'is distinct from oldrow->>'currency_id'or data->>'fiscal_calendar_id'is distinct from oldrow->>'fiscal_calendar_id'or data->>'parent_id'is distinct from oldrow->>'parent_id'or data->>'tax_id'is distinct from oldrow->>'tax_id'or data->>'is_elimination'is distinct from oldrow->>'is_elimination'or not oldcurr<@curr or(not(data->>'is_active')::boolean and(oldrow->>'is_active')::boolean))then raise exception using errcode='55000',message='La subsidiaria utilizada conserva estructura, moneda, calendario, identidad y monedas asignadas.';end if;
 if not(data->>'is_active')::boolean and id=sid then raise exception using errcode='55000',message='Seleccione otra empresa antes de desactivar esta filial.';end if;
 if data->>'fiscal_calendar_id'is distinct from oldrow->>'fiscal_calendar_id'and not organization_master_private.allowed('fiscal-calendars','edit')then raise exception using errcode='42501',message='Requiere permiso explícito para cambiar el calendario fiscal.';end if;end if;
 if data->>'default_up_approver_id'is distinct from oldrow->>'default_up_approver_id'and not company_master_private.up_allowed()then raise exception using errcode='42501',message='Requiere permiso específico de gestión UP.';end if;
 foreach field in array array['default_up_approver_id','tax_supervisor_user_id']loop chosen:=(data->>field)::bigint;if chosen is not null and data->field is distinct from oldrow->field and not exists(select 1 from public.users u join public.user_subsidiaries us using(user_id)where u.user_id=chosen and u.is_active and us.subsidiary_id=id)then raise exception using errcode='42501',message='Usuario de aprobación/supervisión no disponible en la filial.';end if;end loop;
 if data->>'administrative_approver'is not null and data->>'administrative_approver'is distinct from oldrow->>'administrative_approver'then
 if data->>'administrative_approver'!~'^(user|employee):[1-9][0-9]{0,15}$'then raise exception using errcode='22023',message='Aprobador administrativo inválido.';end if;kind:=split_part(data->>'administrative_approver',':',1);chosen:=split_part(data->>'administrative_approver',':',2)::bigint;
 if(kind='user'and not exists(select 1 from public.users u join public.user_subsidiaries us using(user_id)where u.user_id=chosen and u.is_active and us.subsidiary_id=id))or(kind='employee'and not exists(select 1 from public.employees e join public.users u using(user_id)join public.user_subsidiaries us using(user_id)where e.employee_id=chosen and e.is_active and u.is_active and e.subsidiary_id=id and us.subsidiary_id=id))then raise exception using errcode='42501',message='Aprobador administrativo ajeno o inactivo.';end if;end if;
 if(data->>'applies_income_autorent')::boolean then percentage:=(data->>'autorent_percentage')::numeric;if not asset_posting_private.finite(percentage)or percentage<=0 or percentage>1 then raise exception using errcode='22023',message='Porcentaje de autorretención inválido.';end if;perform public.validate_income_autorent_configuration(id,(data->>'country_id')::bigint,true,(data->>'autorent_active_account_id')::bigint,(data->>'autorent_passive_account_id')::bigint,percentage);elsif oldrow is null or p?'applies_income_autorent'then data:=data||jsonb_build_object('autorent_active_account_id',null,'autorent_passive_account_id',null,'autorent_percentage',null);end if;
 end if;
 select string_agg(format('%I',x),','),string_agg(format('v.%I',x),','),string_agg(format('%I=v.%I',x,x),',')into cols,vals,sets from unnest(c.fields)x where id is null or data->x is distinct from oldrow->x;
 if id is null then execute format('insert into public.%I(%s)select %s from jsonb_populate_record(null::public.%I,$1)v returning to_jsonb(%I.*)',c.t,cols,vals,c.t,c.t)into r using data;id:=(r->>c.pk)::bigint;
 elsif cols is not null then execute format('update public.%I x set %s from jsonb_populate_record(null::public.%I,$1)v where x.%I=$2 returning to_jsonb(x)',c.t,sets,c.t,c.pk)into r using data,id;else r:=oldrow;end if;
 if k='subsidiaries'then
 if oldrow is null then insert into public.user_subsidiaries(user_id,subsidiary_id)values(public.app_user_id(),id);end if;
 update public.subsidiary_currencies set is_primary=currency_id=(data->>'currency_id')::bigint where subsidiary_id=id and is_primary is distinct from(currency_id=(data->>'currency_id')::bigint);
 delete from public.subsidiary_currencies where subsidiary_id=id and not currency_id=any(curr);
 insert into public.subsidiary_currencies(subsidiary_id,currency_id,is_primary)select id,x,x=(data->>'currency_id')::bigint from unnest(curr)x where not exists(select 1 from public.subsidiary_currencies where subsidiary_id=id and currency_id=x);
 return company_master_private.dto(jsonb_populate_record(null::public.subsidiaries,r),true);
 end if;return r||jsonb_build_object('_revision',md5(r::text),'_actions',jsonb_build_object('canEdit',organization_master_private.allowed(k,'edit'),'canDelete',organization_master_private.allowed(k,'delete')and not entity_master_private.used('branches',id)));end$$;
create function company_master_private.remove(k text,id bigint,revision text)returns boolean language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=organization_master_private.access(k,'delete');b public.branches;begin if k='subsidiaries'then raise exception using errcode='42501',message='No se permite eliminar subsidiarias y sus dependencias.';end if;perform pg_advisory_xact_lock(793151,1);select *into b from public.branches where branch_id=id for update;if not found or b.subsidiary_id<>sid then raise exception using errcode='42501',message='Sucursal ajena.';end if;if revision is distinct from md5(to_jsonb(b)::text)or entity_master_private.used('branches',id)then raise exception using errcode='55000',message='La sucursal cambió o tiene dependencias.';end if;delete from public.branches where branch_id=id;return true;end$$;
create or replace function public.organization_master_list(p_catalog text)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin if p_catalog in('subsidiaries','branches')then return company_master_private.list(p_catalog);elsif p_catalog in('fiscal-years','fiscal-calendars','accounting-periods')then return fiscal_structure_private.list(p_catalog);elsif p_catalog='cost-centers'then return cost_center_master_private.list();end if;return organization_master_private.organization_master_list(p_catalog);end$$;
create or replace function public.organization_master_options(p_catalog text)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin if p_catalog in('subsidiaries','branches')then return company_master_private.options(p_catalog);elsif p_catalog in('fiscal-years','fiscal-calendars','accounting-periods')then return fiscal_structure_private.options(p_catalog);elsif p_catalog in('financial-creditors','related-companies')then return financial_entity_master_private.options(p_catalog);elsif p_catalog='cost-centers'then return cost_center_master_private.options();end if;return organization_master_private.organization_master_options(p_catalog);end$$;
create or replace function public.save_organization_master(p_catalog text,p_payload jsonb,p_id bigint default null)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin if p_catalog in('subsidiaries','branches')then return company_master_private.save(p_catalog,p_payload,p_id);elsif p_catalog in('fiscal-years','fiscal-calendars','accounting-periods')then return fiscal_structure_private.save(p_catalog,p_payload,p_id);elsif p_catalog in('financial-creditors','related-companies')then return financial_entity_master_private.save(p_catalog,p_payload,p_id);elsif p_catalog='cost-centers'then return cost_center_master_private.save(p_payload,p_id);end if;return organization_master_private.save_organization_master(p_catalog,p_payload,p_id);end$$;
create or replace function public.delete_organization_master(p_catalog text,p_id bigint,p_revision text default null)returns boolean language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin if p_catalog in('subsidiaries','branches')then return company_master_private.remove(p_catalog,p_id,p_revision);elsif p_catalog in('fiscal-years','fiscal-calendars','accounting-periods')then return fiscal_structure_private.remove(p_catalog,p_id,p_revision);elsif p_catalog='cost-centers'then return cost_center_master_private.remove(p_id,p_revision);end if;return organization_master_private.delete_organization_master(p_catalog,p_id,p_revision);end$$;
do $$declare t text;p record;col record;pred text;begin foreach t in array array['subsidiaries','branches','subsidiary_currencies']loop
 for p in select policyname from pg_policies where schemaname='public'and tablename=t loop execute format('drop policy %I on public.%I',p.policyname,t);end loop;execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);
 for col in select column_name from information_schema.columns where table_schema='public'and table_name=t loop execute format('revoke insert(%I),update(%I),select(%I),references(%I)on public.%I from public,anon,authenticated,service_role',col.column_name,col.column_name,col.column_name,col.column_name,t);end loop;
 pred:=case when t='branches'then'company_master_private.branch_visible(subsidiary_id)'else'company_master_private.member(subsidiary_id)'end;execute format('create policy company_master_read on public.%I for select to authenticated using(%s)',t,pred);execute format('grant select on public.%I to authenticated',t);end loop;end$$;
revoke all on all functions in schema company_master_private from public,anon,authenticated,service_role;grant execute on function company_master_private.member(bigint),company_master_private.branch_visible(bigint)to authenticated;
revoke all on function public.organization_master_list(text),public.organization_master_options(text),public.save_organization_master(text,jsonb,bigint),public.delete_organization_master(text,bigint,text),public.organization_company_detail(bigint)from public,anon,authenticated,service_role;
grant execute on function public.organization_master_list(text),public.organization_master_options(text),public.save_organization_master(text,jsonb,bigint),public.delete_organization_master(text,bigint,text),public.organization_company_detail(bigint)to authenticated;
notify pgrst,'reload schema';
